//! FES ocean-tide admittance-inference weight tables (minor waves from the explicit FES2004
//! majors) — machine-generated by `derivations/ocean_tide_admittance.py`. Regenerate, never
//! hand-edit. See that script and [`crate::ocean_tide`] for the theory; weights are validated
//! against `pyfes` in `experiments/ocean_tide_admittance_verify.py`.
//!
//! Each [`InferredWave`] gives a minor constituent's Doodson number and the real weights on
//! the reference-major coefficients: `coef(minor) = Σ weight · coef(ref_doodson)`, applied
//! per geopotential channel (C⁺,S⁺,C⁻,S⁻) at every (n,m). Weights fold the CNES aviso-fes
//! admittance (Cartwright H_eq amplitudes, band frequencies, PMM95B diurnal Love factor) into
//! constants; the runtime does no interpolation.

// Generated real weights carry many significant digits; several share leading digits, and
// the docs use IERS/FES notation (H_eq, PMM95B, C⁺nm) verbatim.
#![allow(
    clippy::unreadable_literal,
    clippy::excessive_precision,
    clippy::doc_markdown
)]

/// One admittance-inferred minor wave: its Doodson number and the real weights on the
/// reference-major coefficients, `coef(minor) = Σ weight · coef(ref)` per channel and (n,m).
pub struct InferredWave {
    /// Minor-wave Doodson number (drives its argument θ in IERS Eq. 6.15), e.g. 227655 for ε2.
    pub doodson: u32,
    /// `(reference-major Doodson, real weight)` contributions; refs are explicit FES2004 waves.
    pub refs: &'static [(u32, f64)],
}

